CREATE TYPE public.app_role AS ENUM ('creator','manager','reviewer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name,avatar_url) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profiles_owner_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'creator', assigned_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id), FOREIGN KEY(workspace_id,user_id) REFERENCES public.workspace_members(workspace_id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE INDEX members_user_idx ON public.workspace_members(user_id); CREATE INDEX roles_user_idx ON public.user_roles(user_id); CREATE INDEX audit_workspace_idx ON public.audit_log(workspace_id,created_at);
CREATE FUNCTION public.is_workspace_member(_workspace_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=_workspace_id AND user_id=auth.uid()) $$;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role,_workspace_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role AND workspace_id=_workspace_id) $$;
REVOKE ALL ON FUNCTION public.is_workspace_member(uuid),public.has_role(uuid,public.app_role,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_workspace_member(uuid),public.has_role(uuid,public.app_role,uuid) TO authenticated;
CREATE POLICY workspace_read ON public.workspaces FOR SELECT TO authenticated USING(public.is_workspace_member(id));
CREATE POLICY members_read ON public.workspace_members FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin',workspace_id));
CREATE POLICY profiles_admin_read ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.user_id=profiles.id AND public.has_role(auth.uid(),'admin',m.workspace_id)));
CREATE POLICY audit_admin_read ON public.audit_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin',workspace_id));
CREATE FUNCTION public.handle_new_markwise_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),100),coalesce(new.email,'')); INSERT INTO public.workspaces(name,created_by) VALUES('My workspace',new.id) RETURNING id INTO w; INSERT INTO public.workspace_members(workspace_id,user_id) VALUES(w,new.id); INSERT INTO public.user_roles(workspace_id,user_id,role) VALUES(w,new.id,'creator'); INSERT INTO public.audit_log(workspace_id,user_id,action,entity_type,entity_id) VALUES(w,new.id,'account.created','profile',new.id); RETURN new; END $$;
REVOKE ALL ON FUNCTION public.handle_new_markwise_user() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER markwise_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_markwise_user();
CREATE FUNCTION public.manage_workspace_member(_workspace_id uuid,_user_id uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prior public.app_role; BEGIN PERFORM 1 FROM public.workspaces WHERE id=_workspace_id FOR UPDATE; IF NOT public.has_role(auth.uid(),'admin',_workspace_id) THEN RAISE EXCEPTION 'Only workspace administrators can manage members'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'Account not found'; END IF; SELECT role INTO prior FROM public.user_roles WHERE workspace_id=_workspace_id AND user_id=_user_id; IF prior='admin' AND _role<>'admin' AND (SELECT count(*) FROM public.user_roles WHERE workspace_id=_workspace_id AND role='admin')<=1 THEN RAISE EXCEPTION 'The last administrator cannot be demoted'; END IF; INSERT INTO public.workspace_members(workspace_id,user_id) VALUES(_workspace_id,_user_id) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(workspace_id,user_id,role,assigned_by) VALUES(_workspace_id,_user_id,_role,auth.uid()) ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=EXCLUDED.role,assigned_by=auth.uid(); INSERT INTO public.audit_log(workspace_id,user_id,action,entity_type,entity_id,metadata) VALUES(_workspace_id,auth.uid(),'member.role_assigned','profile',_user_id,jsonb_build_object('role',_role,'previous_role',prior)); END $$;
CREATE FUNCTION public.add_workspace_member_by_email(_workspace_id uuid,_email text,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin',_workspace_id) THEN RAISE EXCEPTION 'Only workspace administrators can manage members'; END IF; SELECT p.id INTO target FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE lower(p.email)=lower(trim(_email)) AND u.email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'No confirmed account found; ask the user to sign up and confirm their email first'; END IF; PERFORM public.manage_workspace_member(_workspace_id,target,_role); END $$;
CREATE FUNCTION public.rename_workspace(_workspace_id uuid,_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin',_workspace_id) THEN RAISE EXCEPTION 'Only workspace administrators can change workspace settings'; END IF; UPDATE public.workspaces SET name=trim(_name) WHERE id=_workspace_id; INSERT INTO public.audit_log(workspace_id,user_id,action,entity_type,entity_id) VALUES(_workspace_id,auth.uid(),'workspace.updated','workspace',_workspace_id); END $$;
REVOKE ALL ON FUNCTION public.manage_workspace_member(uuid,uuid,public.app_role),public.add_workspace_member_by_email(uuid,text,public.app_role),public.rename_workspace(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.manage_workspace_member(uuid,uuid,public.app_role),public.add_workspace_member_by_email(uuid,text,public.app_role),public.rename_workspace(uuid,text) TO authenticated;
CREATE FUNCTION public.audit_profile_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.full_name IS DISTINCT FROM old.full_name OR new.avatar_url IS DISTINCT FROM old.avatar_url THEN INSERT INTO public.audit_log(workspace_id,user_id,action,entity_type,entity_id) SELECT workspace_id,new.id,'profile.updated','profile',new.id FROM public.workspace_members WHERE user_id=new.id; END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.audit_profile_update() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profile_update_audit AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.audit_profile_update();
CREATE POLICY avatar_owner_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatar_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('png','jpg','jpeg','webp'));
CREATE POLICY avatar_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);